/* ================================================================
   GreenBean Coffee — Shared Stylesheet
   ================================================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:wght@500;600;700&display=swap');

/* ---- Reset & Variables ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --green:        #00824A;
  --green-dark:   #006b3a;
  --green-light:  #e6f5ed;
  --forest:       #32462F;
  --forest-light: #4a5f47;
  --cream:        #F3CEA1;
  --cream-light:  #fdf3e8;
  --white:        #ffffff;
  --off-white:    #f9f7f4;
  --gray-100:     #f5f4f0;
  --gray-200:     #e8e5df;
  --gray-300:     #d4d1ca;
  --gray-500:     #8c8983;
  --gray-700:     #555350;
  --gray-900:     #1d1c1a;
  --text:         #2c2a27;
  --text-light:   #6b6863;
  --radius-sm:    8px;
  --radius:       12px;
  --radius-lg:    20px;
  --radius-xl:    28px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,0.06);
  --shadow:       0 4px 20px rgba(0,0,0,0.08);
  --shadow-lg:    0 8px 40px rgba(0,0,0,0.12);
  --transition:   0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width:    1280px;
  --header-h:     64px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-top: var(--header-h);
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
ul { list-style: none; }

h1, h2, h3, h4 { font-family: 'Playfair Display', Georgia, serif; font-weight: 600; line-height: 1.2; }
h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); }
h3 { font-size: clamp(1.1rem, 2.5vw, 1.5rem); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ---- Buttons ---- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 600; font-size: 0.95rem; padding: 12px 28px;
  border-radius: 50px; transition: var(--transition); white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-outline { border: 2px solid var(--green); color: var(--green); }
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-outline-white { border: 2px solid var(--white); color: var(--white); }
.btn-outline-white:hover { background: var(--white); color: var(--green); }
.btn-dark { background: var(--forest); color: var(--white); }
.btn-dark:hover { background: #1f2e1d; transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ---- Header ---- */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  height: var(--header-h); background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  display: flex; align-items: center;
}

.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}

.logo { display: flex; align-items: center; gap: 10px; font-size: 1.3rem; font-weight: 700; color: var(--forest); }
.logo svg { width: 36px; height: 36px; flex-shrink: 0; }

.nav-main { display: flex; align-items: center; gap: 4px; }
.nav-main a {
  font-weight: 500; font-size: 0.9rem; padding: 8px 16px; border-radius: 50px;
  transition: var(--transition); color: var(--text);
}
.nav-main a:hover, .nav-main a.active { background: var(--gray-100); color: var(--green); }

.nav-actions { display: flex; align-items: center; gap: 8px; }
.nav-actions .btn { font-size: 0.85rem; padding: 8px 18px; }

.menu-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.menu-toggle span { width: 22px; height: 2px; background: var(--text); border-radius: 2px; transition: var(--transition); }

.nav-mobile { display: none; }

/* ---- Hero ---- */
.hero {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 60%, #2d4a28 100%);
  color: var(--white); min-height: 520px;
  display: flex; align-items: center;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,130,74,0.3) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(243,206,161,0.15) 0%, transparent 50%);
}
.hero-content { position: relative; z-index: 2; max-width: 600px; padding: 80px 0; }
.hero h1 { margin-bottom: 24px; }
.hero p { font-size: 1.15rem; opacity: 0.9; margin-bottom: 32px; line-height: 1.7; }
.hero-btns { display: flex; flex-wrap: wrap; gap: 12px; }

.hero-image {
  position: absolute; right: -80px; top: 50%; transform: translateY(-50%);
  width: 520px; height: 520px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  opacity: 0.15; z-index: 1;
}
.hero-image-inner {
  position: absolute; right: 60px; top: 50%; transform: translateY(-50%);
  width: 340px; height: 340px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
  opacity: 0.8; z-index: 1;
}

/* ---- Section Commons ---- */
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.section-label { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--green); margin-bottom: 12px; }
.section-title { margin-bottom: 16px; max-width: 700px; }
.section-body { font-size: 1.05rem; color: var(--text-light); margin-bottom: 28px; max-width: 580px; line-height: 1.7; }

.bg-cream { background: var(--cream-light); }
.bg-forest { background: var(--forest); color: var(--white); }
.bg-green { background: var(--green); color: var(--white); }
.bg-off-white { background: var(--off-white); }

.text-center { text-align: center; }
.text-center .section-body, .text-center .section-title { margin-left: auto; margin-right: auto; }

/* ---- Two-Column Card Layout ---- */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }

.card-visual {
  background: var(--gray-100); border-radius: var(--radius-lg);
  min-height: 360px; display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}

.card-visual-circle {
  width: 200px; height: 200px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
}
.card-visual-circle.green { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-visual-circle.forest { background: linear-gradient(135deg, var(--forest) 0%, #1f2e1d 100%); }

.card-visual-label {
  position: absolute; bottom: 20px; left: 20px; right: 20px;
  font-size: 0.8rem; font-weight: 500; color: var(--text-light);
  text-align: center;
}

/* ---- Promo Strip ---- */
.promo-strip {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 32px 40px; border-radius: var(--radius-lg);
  background: var(--green); color: var(--white); flex-wrap: wrap;
}
.promo-strip h3 { font-size: 1.3rem; }
.promo-strip p { opacity: 0.9; max-width: 500px; }
.promo-strip.forest { background: var(--forest); }

/* ---- Rewards Page ---- */
.rewards-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #2a4a26 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 32px;
  border: 1px solid var(--gray-200); transition: var(--transition);
  text-align: center;
}
.tier-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.tier-card h3 { color: var(--forest); margin-bottom: 8px; }
.tier-card .tier-badge {
  display: inline-block; font-size: 0.8rem; font-weight: 700; padding: 6px 16px;
  border-radius: 50px; margin-bottom: 16px;
}
.tier-card .tier-badge.green { background: #e6f5ed; color: var(--green); }
.tier-card .tier-badge.gold { background: #fdf3e8; color: #b8860b; }
.tier-card .tier-badge.reserve { background: #f0e8f5; color: #6b3fa0; }
.tier-card .tier-stars { font-size: 1.8rem; font-weight: 700; color: var(--text); margin-bottom: 8px; }
.tier-card .tier-stars span { font-size: 0.9rem; font-weight: 500; color: var(--text-light); }
.tier-card ul { text-align: left; margin-top: 16px; }
.tier-card ul li { padding: 6px 0; font-size: 0.9rem; color: var(--text-light); position: relative; padding-left: 20px; }
.tier-card ul li::before { content: '✓'; position: absolute; left: 0; color: var(--green); font-weight: 700; }

/* How It Works */
.steps-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step-card { text-align: center; padding: 24px; }
.step-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 56px; height: 56px; border-radius: 50%; font-size: 1.4rem;
  font-weight: 700; margin-bottom: 16px;
}
.step-num.green { background: var(--green-light); color: var(--green); }
.step-card h3 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 1.1rem; margin-bottom: 8px; }
.step-card p { font-size: 0.9rem; color: var(--text-light); line-height: 1.6; }

/* Redemption Tabs */
.redemption-tabs { display: flex; gap: 4px; flex-wrap: wrap; justify-content: center; margin-bottom: 32px; }
.tab-btn {
  padding: 10px 22px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text); transition: var(--transition); border: 2px solid transparent;
  background: var(--gray-100);
}
.tab-btn:hover { border-color: var(--green); }
.tab-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.redemption-content { display: none; }
.redemption-content.active { display: block; }

.redemption-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 40px;
  border: 1px solid var(--gray-200); text-align: center; max-width: 500px;
  margin: 0 auto;
}
.redemption-card .star-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 2rem; font-weight: 700; color: var(--green); margin-bottom: 16px;
}
.redemption-card .star-badge svg { width: 32px; height: 32px; }
.redemption-card h3 { margin-bottom: 8px; }
.redemption-card .reward-value { font-size: 0.9rem; color: var(--text-light); margin-top: 8px; }

/* Partnerships */
.partnerships { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.partner-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 32px; display: flex; gap: 20px; align-items: flex-start; transition: var(--transition);
}
.partner-card:hover { box-shadow: var(--shadow); }
.partner-icon {
  width: 56px; height: 56px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
}

/* ---- Gift Cards Page ---- */
.gift-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.carousel-wrapper { position: relative; margin-bottom: 48px; }
.carousel-track {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
  padding: 8px 0; scrollbar-width: none;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 260px; scroll-snap-align: start;
  background: var(--white); border-radius: var(--radius-lg); overflow: hidden;
  border: 1px solid var(--gray-200); transition: var(--transition);
}
.carousel-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

.card-design {
  height: 180px; display: flex; align-items: center; justify-content: center;
  font-size: 1rem; font-weight: 600; color: var(--white); text-align: center;
  padding: 16px;
}

.card-design.spring  { background: linear-gradient(135deg, #4a9e4e 0%, #2d6b30 100%); }
.card-design.birthday { background: linear-gradient(135deg, #e8839a 0%, #c45470 100%); }
.card-design.thankyou { background: linear-gradient(135deg, #5b8ec9 0%, #3a5f8a 100%); }
.card-design.celebrate { background: linear-gradient(135deg, #f0a050 0%, #c87820 100%); }
.card-design.star     { background: linear-gradient(135deg, #8b5ec9 0%, #5a30a0 100%); }
.card-design.coffee   { background: linear-gradient(135deg, var(--forest) 0%, #1a2e16 100%); }
.card-design.perk     { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-design.cafe     { background: linear-gradient(135deg, #a0522d 0%, #6b3520 100%); }
.card-design.heritage { background: linear-gradient(135deg, #4a6741 0%, #2a3f26 100%); }
.card-design.treat    { background: linear-gradient(135deg, #d4838a 0%, #9b4a54 100%); }

.card-info { padding: 16px; }
.card-info h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.card-info p { font-size: 0.8rem; color: var(--text-light); }

.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; background: var(--white);
  box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center;
  z-index: 10; transition: var(--transition); font-size: 1.1rem; color: var(--text);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--green); color: var(--white); }
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }

.category-section { margin-bottom: 48px; }
.category-section h3 { margin-bottom: 12px; }

/* Business Gifting */
.biz-gifting {
  background: var(--cream-light); border-radius: var(--radius-lg); padding: 48px;
  display: flex; align-items: center; gap: 48px;
}

/* ---- Menu Page ---- */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 48px; }
.menu-sidebar { position: sticky; top: calc(var(--header-h) + 32px); align-self: start; }
.menu-sidebar h3 { font-family: 'DM Sans', sans-serif; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-light); margin-bottom: 12px; margin-top: 28px; }
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar a {
  display: block; padding: 8px 14px; border-radius: var(--radius-sm); font-size: 0.9rem;
  color: var(--text); transition: var(--transition); font-weight: 500;
}
.menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green-light); color: var(--green); }

.menu-category { margin-bottom: 48px; }
.menu-category h2 { margin-bottom: 8px; }
.menu-category > p { color: var(--text-light); font-size: 0.9rem; margin-bottom: 24px; }

.menu-items { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
.menu-item {
  display: flex; gap: 16px; padding: 16px; border-radius: var(--radius);
  transition: var(--transition); border: 1px solid transparent;
}
.menu-item:hover { border-color: var(--gray-200); box-shadow: var(--shadow-sm); }
.menu-item-img {
  width: 80px; height: 80px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; color: var(--text-light); text-align: center;
}
.menu-item-info h4 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 0.95rem; }
.menu-item-info p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }

/* Breadcrumb */
.breadcrumb { padding: 16px 0; font-size: 0.85rem; color: var(--text-light); }
.breadcrumb a { color: var(--green); }
.breadcrumb span { margin: 0 6px; }

/* ---- Store Locator ---- */
.locator-layout { display: grid; grid-template-columns: 420px 1fr; gap: 0; min-height: calc(100vh - var(--header-h)); }

.locator-sidebar { border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.locator-search-area { padding: 24px; border-bottom: 1px solid var(--gray-200); }
.locator-toggle {
  display: flex; background: var(--gray-100); border-radius: 50px; padding: 4px;
  margin-bottom: 16px;
}
.locator-toggle button {
  flex: 1; padding: 10px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text-light); transition: var(--transition);
}
.locator-toggle button.active { background: var(--white); color: var(--text); box-shadow: var(--shadow-sm); }

.locator-search-box {
  display: flex; align-items: center; gap: 8px;
  background: var(--white); border: 1px solid var(--gray-300); border-radius: var(--radius);
  padding: 10px 16px;
}
.locator-search-box input {
  flex: 1; border: none; outline: none; font: inherit; font-size: 0.9rem;
}
.locator-search-box svg { flex-shrink: 0; color: var(--text-light); }

.locator-filter-btn {
  display: flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 500;
  color: var(--green); margin-top: 12px;
}

.locator-filter-panel { display: none; padding: 0 24px 24px; border-bottom: 1px solid var(--gray-200); }
.locator-filter-panel.open { display: block; }
.locator-filter-panel h4 { font-family: 'DM Sans', sans-serif; font-size: 0.85rem; margin-bottom: 12px; }
.filter-option { display: flex; align-items: center; gap: 10px; padding: 6px 0; font-size: 0.85rem; }
.filter-option label { cursor: pointer; }

.locator-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.locator-result {
  padding: 20px 24px; border-bottom: 1px solid var(--gray-100); cursor: pointer;
  transition: var(--transition);
}
.locator-result:hover { background: var(--gray-100); }
.locator-result h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; }
.locator-result p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }
.locator-result .features { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.locator-result .feature-tag {
  font-size: 0.7rem; font-weight: 500; padding: 3px 10px;
  border-radius: 50px; background: var(--green-light); color: var(--green);
}

.locator-map-area {
  position: relative; background: var(--gray-100);
  display: flex; align-items: center; justify-content: center;
  min-height: 500px;
}
.locator-map-placeholder {
  text-align: center; color: var(--text-light);
}
.locator-map-placeholder svg { width: 80px; height: 80px; margin-bottom: 16px; opacity: 0.5; }
.locator-map-placeholder p { font-size: 0.9rem; }

/* Suggestion Dropdown */
.search-suggestions {
  display: none; position: absolute; top: 100%; left: 0; right: 0;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius);
  box-shadow: var(--shadow-lg); z-index: 100; margin-top: 4px;
}
.search-suggestions.open { display: block; }
.search-suggestions .suggestion-item {
  padding: 12px 16px; font-size: 0.9rem; cursor: pointer; transition: var(--transition);
}
.search-suggestions .suggestion-item:hover { background: var(--gray-100); }

/* ---- Footer ---- */
.site-footer { background: var(--forest); color: var(--white); padding: 60px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; margin-bottom: 48px; }

.footer-col h4 {
  font-family: 'DM Sans', sans-serif; font-size: 0.85rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 20px;
  color: rgba(255,255,255,0.7); cursor: default;
}
.footer-col a {
  display: block; font-size: 0.85rem; color: rgba(255,255,255,0.6);
  padding: 4px 0; transition: var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px;
  font-size: 0.8rem; color: rgba(255,255,255,0.5);
}

.social-links { display: flex; gap: 16px; }
.social-links a { color: rgba(255,255,255,0.6); transition: var(--transition); font-size: 0.85rem; }
.social-links a:hover { color: var(--white); }

/* ---- Cookie Banner ---- */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: var(--white); border-top: 1px solid var(--gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.08); padding: 20px 0;
  transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { display: none; }
.cookie-inner {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; flex-wrap: wrap;
}
.cookie-inner h4 { font-family: 'DM Sans', sans-serif; font-size: 0.9rem; margin-bottom: 4px; }
.cookie-inner p { font-size: 0.8rem; color: var(--text-light); max-width: 600px; }
.cookie-btns { display: flex; gap: 10px; flex-shrink: 0; }

/* ---- Responsive ---- */
@media (max-width: 1024px) {
  .two-col { grid-template-columns: 1fr; gap: 32px; }
  .card-visual { min-height: 260px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 440px; margin: 0 auto; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid var(--gray-200); padding-bottom: 20px; }
  .menu-sidebar h3 { display: none; }
  .menu-sidebar a { display: inline-block; padding: 6px 14px; border-radius: 50px; font-size: 0.8rem; border: 1px solid var(--gray-200); }
  .menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green); color: var(--white); border-color: var(--green); }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-map-area { min-height: 300px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .partnerships { grid-template-columns: 1fr; }
  .steps-row { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .biz-gifting { flex-direction: column; text-align: center; }
  .nav-main { display: none; }
  .menu-toggle { display: flex; }

  .nav-mobile {
    display: none; position: fixed; top: var(--header-h); left: 0; right: 0; bottom: 0;
    background: var(--white); z-index: 999; flex-direction: column; padding: 24px;
  }
  .nav-mobile.open { display: flex; }
  .nav-mobile a {
    display: block; padding: 14px 20px; font-size: 1.05rem; font-weight: 500;
    border-radius: var(--radius); transition: var(--transition);
  }
  .nav-mobile a:hover { background: var(--gray-100); }
  .nav-mobile .mobile-actions { margin-top: 24px; padding-top: 24px; border-top: 1px solid var(--gray-200); display: flex; flex-direction: column; gap: 12px; }
}

@media (max-width: 768px) {
  .hero { min-height: 420px; }
  .hero-content { padding: 60px 0; }
  .hero-image { width: 300px; height: 300px; right: -120px; }
  .footer-grid { grid-template-columns: 1fr; }

  .footer-col h4 {
    cursor: pointer; position: relative; padding-right: 24px; margin-bottom: 0; padding: 12px 0;
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }
  .footer-col h4::after {
    content: '+'; position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
    font-size: 1.2rem; transition: var(--transition);
  }
  .footer-col.open h4::after { content: '−'; }
  .footer-col-links { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
  .footer-col.open .footer-col-links { max-height: 600px; }
  .footer-col a { padding: 6px 0; }

  .section { padding: 48px 0; }
  .promo-strip { flex-direction: column; text-align: center; }
  .locator-sidebar { border-right: none; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-btns { justify-content: center; }
  .header-inner { padding: 0 16px; }
  .container { padding: 0 16px; }
}

@media (max-width: 480px) {
  .hero { min-height: 360px; }
  .hero h1 { font-size: 1.8rem; }
  .carousel-card { flex: 0 0 220px; }
  .redemption-card { padding: 24px; }
}

/* ================================================================
   GreenBean Coffee — Shared Stylesheet
   ================================================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:wght@500;600;700&display=swap');

/* ---- Reset & Variables ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --green:        #00824A;
  --green-dark:   #006b3a;
  --green-light:  #e6f5ed;
  --forest:       #32462F;
  --forest-light: #4a5f47;
  --cream:        #F3CEA1;
  --cream-light:  #fdf3e8;
  --white:        #ffffff;
  --off-white:    #f9f7f4;
  --gray-100:     #f5f4f0;
  --gray-200:     #e8e5df;
  --gray-300:     #d4d1ca;
  --gray-500:     #8c8983;
  --gray-700:     #555350;
  --gray-900:     #1d1c1a;
  --text:         #2c2a27;
  --text-light:   #6b6863;
  --radius-sm:    8px;
  --radius:       12px;
  --radius-lg:    20px;
  --radius-xl:    28px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,0.06);
  --shadow:       0 4px 20px rgba(0,0,0,0.08);
  --shadow-lg:    0 8px 40px rgba(0,0,0,0.12);
  --transition:   0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width:    1280px;
  --header-h:     64px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-top: var(--header-h);
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
ul { list-style: none; }

h1, h2, h3, h4 { font-family: 'Playfair Display', Georgia, serif; font-weight: 600; line-height: 1.2; }
h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); }
h3 { font-size: clamp(1.1rem, 2.5vw, 1.5rem); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ---- Buttons ---- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 600; font-size: 0.95rem; padding: 12px 28px;
  border-radius: 50px; transition: var(--transition); white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-outline { border: 2px solid var(--green); color: var(--green); }
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-outline-white { border: 2px solid var(--white); color: var(--white); }
.btn-outline-white:hover { background: var(--white); color: var(--green); }
.btn-dark { background: var(--forest); color: var(--white); }
.btn-dark:hover { background: #1f2e1d; transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ---- Header ---- */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  height: var(--header-h); background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  display: flex; align-items: center;
}

.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}

.logo { display: flex; align-items: center; gap: 10px; font-size: 1.3rem; font-weight: 700; color: var(--forest); }
.logo svg { width: 36px; height: 36px; flex-shrink: 0; }

.nav-main { display: flex; align-items: center; gap: 4px; }
.nav-main a {
  font-weight: 500; font-size: 0.9rem; padding: 8px 16px; border-radius: 50px;
  transition: var(--transition); color: var(--text);
}
.nav-main a:hover, .nav-main a.active { background: var(--gray-100); color: var(--green); }

.nav-actions { display: flex; align-items: center; gap: 8px; }
.nav-actions .btn { font-size: 0.85rem; padding: 8px 18px; }

.menu-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.menu-toggle span { width: 22px; height: 2px; background: var(--text); border-radius: 2px; transition: var(--transition); }

.nav-mobile { display: none; }

/* ---- Hero ---- */
.hero {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 60%, #2d4a28 100%);
  color: var(--white); min-height: 520px;
  display: flex; align-items: center;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,130,74,0.3) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(243,206,161,0.15) 0%, transparent 50%);
}
.hero-content { position: relative; z-index: 2; max-width: 600px; padding: 80px 0; }
.hero h1 { margin-bottom: 24px; }
.hero p { font-size: 1.15rem; opacity: 0.9; margin-bottom: 32px; line-height: 1.7; }
.hero-btns { display: flex; flex-wrap: wrap; gap: 12px; }

.hero-image {
  position: absolute; right: -80px; top: 50%; transform: translateY(-50%);
  width: 520px; height: 520px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  opacity: 0.15; z-index: 1;
}
.hero-image-inner {
  position: absolute; right: 60px; top: 50%; transform: translateY(-50%);
  width: 340px; height: 340px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
  opacity: 0.8; z-index: 1;
}

/* ---- Section Commons ---- */
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.section-label { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--green); margin-bottom: 12px; }
.section-title { margin-bottom: 16px; max-width: 700px; }
.section-body { font-size: 1.05rem; color: var(--text-light); margin-bottom: 28px; max-width: 580px; line-height: 1.7; }

.bg-cream { background: var(--cream-light); }
.bg-forest { background: var(--forest); color: var(--white); }
.bg-green { background: var(--green); color: var(--white); }
.bg-off-white { background: var(--off-white); }

.text-center { text-align: center; }
.text-center .section-body, .text-center .section-title { margin-left: auto; margin-right: auto; }

/* ---- Two-Column Card Layout ---- */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }

.card-visual {
  background: var(--gray-100); border-radius: var(--radius-lg);
  min-height: 360px; display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}

.card-visual-circle {
  width: 200px; height: 200px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
}
.card-visual-circle.green { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-visual-circle.forest { background: linear-gradient(135deg, var(--forest) 0%, #1f2e1d 100%); }

.card-visual-label {
  position: absolute; bottom: 20px; left: 20px; right: 20px;
  font-size: 0.8rem; font-weight: 500; color: var(--text-light);
  text-align: center;
}

/* ---- Promo Strip ---- */
.promo-strip {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 32px 40px; border-radius: var(--radius-lg);
  background: var(--green); color: var(--white); flex-wrap: wrap;
}
.promo-strip h3 { font-size: 1.3rem; }
.promo-strip p { opacity: 0.9; max-width: 500px; }
.promo-strip.forest { background: var(--forest); }

/* ---- Rewards Page ---- */
.rewards-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #2a4a26 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 32px;
  border: 1px solid var(--gray-200); transition: var(--transition);
  text-align: center;
}
.tier-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.tier-card h3 { color: var(--forest); margin-bottom: 8px; }
.tier-card .tier-badge {
  display: inline-block; font-size: 0.8rem; font-weight: 700; padding: 6px 16px;
  border-radius: 50px; margin-bottom: 16px;
}
.tier-card .tier-badge.green { background: #e6f5ed; color: var(--green); }
.tier-card .tier-badge.gold { background: #fdf3e8; color: #b8860b; }
.tier-card .tier-badge.reserve { background: #f0e8f5; color: #6b3fa0; }
.tier-card .tier-stars { font-size: 1.8rem; font-weight: 700; color: var(--text); margin-bottom: 8px; }
.tier-card .tier-stars span { font-size: 0.9rem; font-weight: 500; color: var(--text-light); }
.tier-card ul { text-align: left; margin-top: 16px; }
.tier-card ul li { padding: 6px 0; font-size: 0.9rem; color: var(--text-light); position: relative; padding-left: 20px; }
.tier-card ul li::before { content: '✓'; position: absolute; left: 0; color: var(--green); font-weight: 700; }

/* How It Works */
.steps-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step-card { text-align: center; padding: 24px; }
.step-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 56px; height: 56px; border-radius: 50%; font-size: 1.4rem;
  font-weight: 700; margin-bottom: 16px;
}
.step-num.green { background: var(--green-light); color: var(--green); }
.step-card h3 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 1.1rem; margin-bottom: 8px; }
.step-card p { font-size: 0.9rem; color: var(--text-light); line-height: 1.6; }

/* Redemption Tabs */
.redemption-tabs { display: flex; gap: 4px; flex-wrap: wrap; justify-content: center; margin-bottom: 32px; }
.tab-btn {
  padding: 10px 22px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text); transition: var(--transition); border: 2px solid transparent;
  background: var(--gray-100);
}
.tab-btn:hover { border-color: var(--green); }
.tab-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.redemption-content { display: none; }
.redemption-content.active { display: block; }

.redemption-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 40px;
  border: 1px solid var(--gray-200); text-align: center; max-width: 500px;
  margin: 0 auto;
}
.redemption-card .star-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 2rem; font-weight: 700; color: var(--green); margin-bottom: 16px;
}
.redemption-card .star-badge svg { width: 32px; height: 32px; }
.redemption-card h3 { margin-bottom: 8px; }
.redemption-card .reward-value { font-size: 0.9rem; color: var(--text-light); margin-top: 8px; }

/* Partnerships */
.partnerships { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.partner-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 32px; display: flex; gap: 20px; align-items: flex-start; transition: var(--transition);
}
.partner-card:hover { box-shadow: var(--shadow); }
.partner-icon {
  width: 56px; height: 56px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
}

/* ---- Gift Cards Page ---- */
.gift-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.carousel-wrapper { position: relative; margin-bottom: 48px; }
.carousel-track {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
  padding: 8px 0; scrollbar-width: none;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 260px; scroll-snap-align: start;
  background: var(--white); border-radius: var(--radius-lg); overflow: hidden;
  border: 1px solid var(--gray-200); transition: var(--transition);
}
.carousel-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

.card-design {
  height: 180px; display: flex; align-items: center; justify-content: center;
  font-size: 1rem; font-weight: 600; color: var(--white); text-align: center;
  padding: 16px;
}

.card-design.spring  { background: linear-gradient(135deg, #4a9e4e 0%, #2d6b30 100%); }
.card-design.birthday { background: linear-gradient(135deg, #e8839a 0%, #c45470 100%); }
.card-design.thankyou { background: linear-gradient(135deg, #5b8ec9 0%, #3a5f8a 100%); }
.card-design.celebrate { background: linear-gradient(135deg, #f0a050 0%, #c87820 100%); }
.card-design.star     { background: linear-gradient(135deg, #8b5ec9 0%, #5a30a0 100%); }
.card-design.coffee   { background: linear-gradient(135deg, var(--forest) 0%, #1a2e16 100%); }
.card-design.perk     { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-design.cafe     { background: linear-gradient(135deg, #a0522d 0%, #6b3520 100%); }
.card-design.heritage { background: linear-gradient(135deg, #4a6741 0%, #2a3f26 100%); }
.card-design.treat    { background: linear-gradient(135deg, #d4838a 0%, #9b4a54 100%); }

.card-info { padding: 16px; }
.card-info h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.card-info p { font-size: 0.8rem; color: var(--text-light); }

.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; background: var(--white);
  box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center;
  z-index: 10; transition: var(--transition); font-size: 1.1rem; color: var(--text);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--green); color: var(--white); }
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }

.category-section { margin-bottom: 48px; }
.category-section h3 { margin-bottom: 12px; }

/* Business Gifting */
.biz-gifting {
  background: var(--cream-light); border-radius: var(--radius-lg); padding: 48px;
  display: flex; align-items: center; gap: 48px;
}

/* ---- Menu Page ---- */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 48px; }
.menu-sidebar { position: sticky; top: calc(var(--header-h) + 32px); align-self: start; }
.menu-sidebar h3 { font-family: 'DM Sans', sans-serif; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-light); margin-bottom: 12px; margin-top: 28px; }
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar a {
  display: block; padding: 8px 14px; border-radius: var(--radius-sm); font-size: 0.9rem;
  color: var(--text); transition: var(--transition); font-weight: 500;
}
.menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green-light); color: var(--green); }

.menu-category { margin-bottom: 48px; }
.menu-category h2 { margin-bottom: 8px; }
.menu-category > p { color: var(--text-light); font-size: 0.9rem; margin-bottom: 24px; }

.menu-items { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
.menu-item {
  display: flex; gap: 16px; padding: 16px; border-radius: var(--radius);
  transition: var(--transition); border: 1px solid transparent;
}
.menu-item:hover { border-color: var(--gray-200); box-shadow: var(--shadow-sm); }
.menu-item-img {
  width: 80px; height: 80px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; color: var(--text-light); text-align: center;
}
.menu-item-info h4 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 0.95rem; }
.menu-item-info p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }

/* Breadcrumb */
.breadcrumb { padding: 16px 0; font-size: 0.85rem; color: var(--text-light); }
.breadcrumb a { color: var(--green); }
.breadcrumb span { margin: 0 6px; }

/* ---- Store Locator ---- */
.locator-layout { display: grid; grid-template-columns: 420px 1fr; gap: 0; min-height: calc(100vh - var(--header-h)); }

.locator-sidebar { border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.locator-search-area { padding: 24px; border-bottom: 1px solid var(--gray-200); }
.locator-toggle {
  display: flex; background: var(--gray-100); border-radius: 50px; padding: 4px;
  margin-bottom: 16px;
}
.locator-toggle button {
  flex: 1; padding: 10px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text-light); transition: var(--transition);
}
.locator-toggle button.active { background: var(--white); color: var(--text); box-shadow: var(--shadow-sm); }

.locator-search-box {
  display: flex; align-items: center; gap: 8px;
  background: var(--white); border: 1px solid var(--gray-300); border-radius: var(--radius);
  padding: 10px 16px;
}
.locator-search-box input {
  flex: 1; border: none; outline: none; font: inherit; font-size: 0.9rem;
}
.locator-search-box svg { flex-shrink: 0; color: var(--text-light); }

.locator-filter-btn {
  display: flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 500;
  color: var(--green); margin-top: 12px;
}

.locator-filter-panel { display: none; padding: 0 24px 24px; border-bottom: 1px solid var(--gray-200); }
.locator-filter-panel.open { display: block; }
.locator-filter-panel h4 { font-family: 'DM Sans', sans-serif; font-size: 0.85rem; margin-bottom: 12px; }
.filter-option { display: flex; align-items: center; gap: 10px; padding: 6px 0; font-size: 0.85rem; }
.filter-option label { cursor: pointer; }

.locator-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.locator-result {
  padding: 20px 24px; border-bottom: 1px solid var(--gray-100); cursor: pointer;
  transition: var(--transition);
}
.locator-result:hover { background: var(--gray-100); }
.locator-result h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; }
.locator-result p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }
.locator-result .features { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.locator-result .feature-tag {
  font-size: 0.7rem; font-weight: 500; padding: 3px 10px;
  border-radius: 50px; background: var(--green-light); color: var(--green);
}

.locator-map-area {
  position: relative; background: var(--gray-100);
  display: flex; align-items: center; justify-content: center;
  min-height: 500px;
}
.locator-map-placeholder {
  text-align: center; color: var(--text-light);
}
.locator-map-placeholder svg { width: 80px; height: 80px; margin-bottom: 16px; opacity: 0.5; }
.locator-map-placeholder p { font-size: 0.9rem; }

/* Suggestion Dropdown */
.search-suggestions {
  display: none; position: absolute; top: 100%; left: 0; right: 0;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius);
  box-shadow: var(--shadow-lg); z-index: 100; margin-top: 4px;
}
.search-suggestions.open { display: block; }
.search-suggestions .suggestion-item {
  padding: 12px 16px; font-size: 0.9rem; cursor: pointer; transition: var(--transition);
}
.search-suggestions .suggestion-item:hover { background: var(--gray-100); }

/* ---- Footer ---- */
.site-footer { background: var(--forest); color: var(--white); padding: 60px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; margin-bottom: 48px; }

.footer-col h4 {
  font-family: 'DM Sans', sans-serif; font-size: 0.85rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 20px;
  color: rgba(255,255,255,0.7); cursor: default;
}
.footer-col a {
  display: block; font-size: 0.85rem; color: rgba(255,255,255,0.6);
  padding: 4px 0; transition: var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px;
  font-size: 0.8rem; color: rgba(255,255,255,0.5);
}

.social-links { display: flex; gap: 16px; }
.social-links a { color: rgba(255,255,255,0.6); transition: var(--transition); font-size: 0.85rem; }
.social-links a:hover { color: var(--white); }

/* ---- Cookie Banner ---- */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: var(--white); border-top: 1px solid var(--gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.08); padding: 20px 0;
  transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { display: none; }
.cookie-inner {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; flex-wrap: wrap;
}
.cookie-inner h4 { font-family: 'DM Sans', sans-serif; font-size: 0.9rem; margin-bottom: 4px; }
.cookie-inner p { font-size: 0.8rem; color: var(--text-light); max-width: 600px; }
.cookie-btns { display: flex; gap: 10px; flex-shrink: 0; }

/* ---- Responsive ---- */
@media (max-width: 1024px) {
  .two-col { grid-template-columns: 1fr; gap: 32px; }
  .card-visual { min-height: 260px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 440px; margin: 0 auto; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid var(--gray-200); padding-bottom: 20px; }
  .menu-sidebar h3 { display: none; }
  .menu-sidebar a { display: inline-block; padding: 6px 14px; border-radius: 50px; font-size: 0.8rem; border: 1px solid var(--gray-200); }
  .menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green); color: var(--white); border-color: var(--green); }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-map-area { min-height: 300px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .partnerships { grid-template-columns: 1fr; }
  .steps-row { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .biz-gifting { flex-direction: column; text-align: center; }
  .nav-main { display: none; }
  .menu-toggle { display: flex; }

  .nav-mobile {
    display: none; position: fixed; top: var(--header-h); left: 0; right: 0; bottom: 0;
    background: var(--white); z-index: 999; flex-direction: column; padding: 24px;
  }
  .nav-mobile.open { display: flex; }
  .nav-mobile a {
    display: block; padding: 14px 20px; font-size: 1.05rem; font-weight: 500;
    border-radius: var(--radius); transition: var(--transition);
  }
  .nav-mobile a:hover { background: var(--gray-100); }
  .nav-mobile .mobile-actions { margin-top: 24px; padding-top: 24px; border-top: 1px solid var(--gray-200); display: flex; flex-direction: column; gap: 12px; }
}

@media (max-width: 768px) {
  .hero { min-height: 420px; }
  .hero-content { padding: 60px 0; }
  .hero-image { width: 300px; height: 300px; right: -120px; }
  .footer-grid { grid-template-columns: 1fr; }

  .footer-col h4 {
    cursor: pointer; position: relative; padding-right: 24px; margin-bottom: 0; padding: 12px 0;
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }
  .footer-col h4::after {
    content: '+'; position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
    font-size: 1.2rem; transition: var(--transition);
  }
  .footer-col.open h4::after { content: '−'; }
  .footer-col-links { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
  .footer-col.open .footer-col-links { max-height: 600px; }
  .footer-col a { padding: 6px 0; }

  .section { padding: 48px 0; }
  .promo-strip { flex-direction: column; text-align: center; }
  .locator-sidebar { border-right: none; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-btns { justify-content: center; }
  .header-inner { padding: 0 16px; }
  .container { padding: 0 16px; }
}

@media (max-width: 480px) {
  .hero { min-height: 360px; }
  .hero h1 { font-size: 1.8rem; }
  .carousel-card { flex: 0 0 220px; }
  .redemption-card { padding: 24px; }
}

raw_arguments.content:
/* ================================================================
   GreenBean Coffee — Shared Stylesheet
   ================================================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:wght@500;600;700&display=swap');

/* ---- Reset & Variables ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --green:        #00824A;
  --green-dark:   #006b3a;
  --green-light:  #e6f5ed;
  --forest:       #32462F;
  --forest-light: #4a5f47;
  --cream:        #F3CEA1;
  --cream-light:  #fdf3e8;
  --white:        #ffffff;
  --off-white:    #f9f7f4;
  --gray-100:     #f5f4f0;
  --gray-200:     #e8e5df;
  --gray-300:     #d4d1ca;
  --gray-500:     #8c8983;
  --gray-700:     #555350;
  --gray-900:     #1d1c1a;
  --text:         #2c2a27;
  --text-light:   #6b6863;
  --radius-sm:    8px;
  --radius:       12px;
  --radius-lg:    20px;
  --radius-xl:    28px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,0.06);
  --shadow:       0 4px 20px rgba(0,0,0,0.08);
  --shadow-lg:    0 8px 40px rgba(0,0,0,0.12);
  --transition:   0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width:    1280px;
  --header-h:     64px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-top: var(--header-h);
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
ul { list-style: none; }

h1, h2, h3, h4 { font-family: 'Playfair Display', Georgia, serif; font-weight: 600; line-height: 1.2; }
h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); }
h3 { font-size: clamp(1.1rem, 2.5vw, 1.5rem); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ---- Buttons ---- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 600; font-size: 0.95rem; padding: 12px 28px;
  border-radius: 50px; transition: var(--transition); white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-outline { border: 2px solid var(--green); color: var(--green); }
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-outline-white { border: 2px solid var(--white); color: var(--white); }
.btn-outline-white:hover { background: var(--white); color: var(--green); }
.btn-dark { background: var(--forest); color: var(--white); }
.btn-dark:hover { background: #1f2e1d; transform: translateY(-1px); box-shadow: var(--shadow); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ---- Header ---- */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  height: var(--header-h); background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  display: flex; align-items: center;
}

.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}

.logo { display: flex; align-items: center; gap: 10px; font-size: 1.3rem; font-weight: 700; color: var(--forest); }
.logo svg { width: 36px; height: 36px; flex-shrink: 0; }

.nav-main { display: flex; align-items: center; gap: 4px; }
.nav-main a {
  font-weight: 500; font-size: 0.9rem; padding: 8px 16px; border-radius: 50px;
  transition: var(--transition); color: var(--text);
}
.nav-main a:hover, .nav-main a.active { background: var(--gray-100); color: var(--green); }

.nav-actions { display: flex; align-items: center; gap: 8px; }
.nav-actions .btn { font-size: 0.85rem; padding: 8px 18px; }

.menu-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.menu-toggle span { width: 22px; height: 2px; background: var(--text); border-radius: 2px; transition: var(--transition); }

.nav-mobile { display: none; }

/* ---- Hero ---- */
.hero {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 60%, #2d4a28 100%);
  color: var(--white); min-height: 520px;
  display: flex; align-items: center;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,130,74,0.3) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(243,206,161,0.15) 0%, transparent 50%);
}
.hero-content { position: relative; z-index: 2; max-width: 600px; padding: 80px 0; }
.hero h1 { margin-bottom: 24px; }
.hero p { font-size: 1.15rem; opacity: 0.9; margin-bottom: 32px; line-height: 1.7; }
.hero-btns { display: flex; flex-wrap: wrap; gap: 12px; }

.hero-image {
  position: absolute; right: -80px; top: 50%; transform: translateY(-50%);
  width: 520px; height: 520px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  opacity: 0.15; z-index: 1;
}
.hero-image-inner {
  position: absolute; right: 60px; top: 50%; transform: translateY(-50%);
  width: 340px; height: 340px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
  opacity: 0.8; z-index: 1;
}

/* ---- Section Commons ---- */
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.section-label { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--green); margin-bottom: 12px; }
.section-title { margin-bottom: 16px; max-width: 700px; }
.section-body { font-size: 1.05rem; color: var(--text-light); margin-bottom: 28px; max-width: 580px; line-height: 1.7; }

.bg-cream { background: var(--cream-light); }
.bg-forest { background: var(--forest); color: var(--white); }
.bg-green { background: var(--green); color: var(--white); }
.bg-off-white { background: var(--off-white); }

.text-center { text-align: center; }
.text-center .section-body, .text-center .section-title { margin-left: auto; margin-right: auto; }

/* ---- Two-Column Card Layout ---- */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }

.card-visual {
  background: var(--gray-100); border-radius: var(--radius-lg);
  min-height: 360px; display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}

.card-visual-circle {
  width: 200px; height: 200px; border-radius: 50%;
  background: linear-gradient(135deg, var(--cream) 0%, #e8b87a 100%);
}
.card-visual-circle.green { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-visual-circle.forest { background: linear-gradient(135deg, var(--forest) 0%, #1f2e1d 100%); }

.card-visual-label {
  position: absolute; bottom: 20px; left: 20px; right: 20px;
  font-size: 0.8rem; font-weight: 500; color: var(--text-light);
  text-align: center;
}

/* ---- Promo Strip ---- */
.promo-strip {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 32px 40px; border-radius: var(--radius-lg);
  background: var(--green); color: var(--white); flex-wrap: wrap;
}
.promo-strip h3 { font-size: 1.3rem; }
.promo-strip p { opacity: 0.9; max-width: 500px; }
.promo-strip.forest { background: var(--forest); }

/* ---- Rewards Page ---- */
.rewards-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #2a4a26 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 32px;
  border: 1px solid var(--gray-200); transition: var(--transition);
  text-align: center;
}
.tier-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.tier-card h3 { color: var(--forest); margin-bottom: 8px; }
.tier-card .tier-badge {
  display: inline-block; font-size: 0.8rem; font-weight: 700; padding: 6px 16px;
  border-radius: 50px; margin-bottom: 16px;
}
.tier-card .tier-badge.green { background: #e6f5ed; color: var(--green); }
.tier-card .tier-badge.gold { background: #fdf3e8; color: #b8860b; }
.tier-card .tier-badge.reserve { background: #f0e8f5; color: #6b3fa0; }
.tier-card .tier-stars { font-size: 1.8rem; font-weight: 700; color: var(--text); margin-bottom: 8px; }
.tier-card .tier-stars span { font-size: 0.9rem; font-weight: 500; color: var(--text-light); }
.tier-card ul { text-align: left; margin-top: 16px; }
.tier-card ul li { padding: 6px 0; font-size: 0.9rem; color: var(--text-light); position: relative; padding-left: 20px; }
.tier-card ul li::before { content: '✓'; position: absolute; left: 0; color: var(--green); font-weight: 700; }

/* How It Works */
.steps-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step-card { text-align: center; padding: 24px; }
.step-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 56px; height: 56px; border-radius: 50%; font-size: 1.4rem;
  font-weight: 700; margin-bottom: 16px;
}
.step-num.green { background: var(--green-light); color: var(--green); }
.step-card h3 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 1.1rem; margin-bottom: 8px; }
.step-card p { font-size: 0.9rem; color: var(--text-light); line-height: 1.6; }

/* Redemption Tabs */
.redemption-tabs { display: flex; gap: 4px; flex-wrap: wrap; justify-content: center; margin-bottom: 32px; }
.tab-btn {
  padding: 10px 22px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text); transition: var(--transition); border: 2px solid transparent;
  background: var(--gray-100);
}
.tab-btn:hover { border-color: var(--green); }
.tab-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.redemption-content { display: none; }
.redemption-content.active { display: block; }

.redemption-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 40px;
  border: 1px solid var(--gray-200); text-align: center; max-width: 500px;
  margin: 0 auto;
}
.redemption-card .star-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 2rem; font-weight: 700; color: var(--green); margin-bottom: 16px;
}
.redemption-card .star-badge svg { width: 32px; height: 32px; }
.redemption-card h3 { margin-bottom: 8px; }
.redemption-card .reward-value { font-size: 0.9rem; color: var(--text-light); margin-top: 8px; }

/* Partnerships */
.partnerships { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.partner-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 32px; display: flex; gap: 20px; align-items: flex-start; transition: var(--transition);
}
.partner-card:hover { box-shadow: var(--shadow); }
.partner-icon {
  width: 56px; height: 56px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
}

/* ---- Gift Cards Page ---- */
.gift-hero-section {
  background: linear-gradient(135deg, var(--forest) 0%, #1f3a1c 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}

.carousel-wrapper { position: relative; margin-bottom: 48px; }
.carousel-track {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
  padding: 8px 0; scrollbar-width: none;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 260px; scroll-snap-align: start;
  background: var(--white); border-radius: var(--radius-lg); overflow: hidden;
  border: 1px solid var(--gray-200); transition: var(--transition);
}
.carousel-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

.card-design {
  height: 180px; display: flex; align-items: center; justify-content: center;
  font-size: 1rem; font-weight: 600; color: var(--white); text-align: center;
  padding: 16px;
}

.card-design.spring  { background: linear-gradient(135deg, #4a9e4e 0%, #2d6b30 100%); }
.card-design.birthday { background: linear-gradient(135deg, #e8839a 0%, #c45470 100%); }
.card-design.thankyou { background: linear-gradient(135deg, #5b8ec9 0%, #3a5f8a 100%); }
.card-design.celebrate { background: linear-gradient(135deg, #f0a050 0%, #c87820 100%); }
.card-design.star     { background: linear-gradient(135deg, #8b5ec9 0%, #5a30a0 100%); }
.card-design.coffee   { background: linear-gradient(135deg, var(--forest) 0%, #1a2e16 100%); }
.card-design.perk     { background: linear-gradient(135deg, var(--green) 0%, #005a30 100%); }
.card-design.cafe     { background: linear-gradient(135deg, #a0522d 0%, #6b3520 100%); }
.card-design.heritage { background: linear-gradient(135deg, #4a6741 0%, #2a3f26 100%); }
.card-design.treat    { background: linear-gradient(135deg, #d4838a 0%, #9b4a54 100%); }

.card-info { padding: 16px; }
.card-info h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.card-info p { font-size: 0.8rem; color: var(--text-light); }

.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; background: var(--white);
  box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center;
  z-index: 10; transition: var(--transition); font-size: 1.1rem; color: var(--text);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--green); color: var(--white); }
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }

.category-section { margin-bottom: 48px; }
.category-section h3 { margin-bottom: 12px; }

/* Business Gifting */
.biz-gifting {
  background: var(--cream-light); border-radius: var(--radius-lg); padding: 48px;
  display: flex; align-items: center; gap: 48px;
}

/* ---- Menu Page ---- */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 48px; }
.menu-sidebar { position: sticky; top: calc(var(--header-h) + 32px); align-self: start; }
.menu-sidebar h3 { font-family: 'DM Sans', sans-serif; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-light); margin-bottom: 12px; margin-top: 28px; }
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar a {
  display: block; padding: 8px 14px; border-radius: var(--radius-sm); font-size: 0.9rem;
  color: var(--text); transition: var(--transition); font-weight: 500;
}
.menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green-light); color: var(--green); }

.menu-category { margin-bottom: 48px; }
.menu-category h2 { margin-bottom: 8px; }
.menu-category > p { color: var(--text-light); font-size: 0.9rem; margin-bottom: 24px; }

.menu-items { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
.menu-item {
  display: flex; gap: 16px; padding: 16px; border-radius: var(--radius);
  transition: var(--transition); border: 1px solid transparent;
}
.menu-item:hover { border-color: var(--gray-200); box-shadow: var(--shadow-sm); }
.menu-item-img {
  width: 80px; height: 80px; border-radius: var(--radius); flex-shrink: 0;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; color: var(--text-light); text-align: center;
}
.menu-item-info h4 { font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: 0.95rem; }
.menu-item-info p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }

/* Breadcrumb */
.breadcrumb { padding: 16px 0; font-size: 0.85rem; color: var(--text-light); }
.breadcrumb a { color: var(--green); }
.breadcrumb span { margin: 0 6px; }

/* ---- Store Locator ---- */
.locator-layout { display: grid; grid-template-columns: 420px 1fr; gap: 0; min-height: calc(100vh - var(--header-h)); }

.locator-sidebar { border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.locator-search-area { padding: 24px; border-bottom: 1px solid var(--gray-200); }
.locator-toggle {
  display: flex; background: var(--gray-100); border-radius: 50px; padding: 4px;
  margin-bottom: 16px;
}
.locator-toggle button {
  flex: 1; padding: 10px; border-radius: 50px; font-weight: 600; font-size: 0.85rem;
  color: var(--text-light); transition: var(--transition);
}
.locator-toggle button.active { background: var(--white); color: var(--text); box-shadow: var(--shadow-sm); }

.locator-search-box {
  display: flex; align-items: center; gap: 8px;
  background: var(--white); border: 1px solid var(--gray-300); border-radius: var(--radius);
  padding: 10px 16px;
}
.locator-search-box input {
  flex: 1; border: none; outline: none; font: inherit; font-size: 0.9rem;
}
.locator-search-box svg { flex-shrink: 0; color: var(--text-light); }

.locator-filter-btn {
  display: flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 500;
  color: var(--green); margin-top: 12px;
}

.locator-filter-panel { display: none; padding: 0 24px 24px; border-bottom: 1px solid var(--gray-200); }
.locator-filter-panel.open { display: block; }
.locator-filter-panel h4 { font-family: 'DM Sans', sans-serif; font-size: 0.85rem; margin-bottom: 12px; }
.filter-option { display: flex; align-items: center; gap: 10px; padding: 6px 0; font-size: 0.85rem; }
.filter-option label { cursor: pointer; }

.locator-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.locator-result {
  padding: 20px 24px; border-bottom: 1px solid var(--gray-100); cursor: pointer;
  transition: var(--transition);
}
.locator-result:hover { background: var(--gray-100); }
.locator-result h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 600; }
.locator-result p { font-size: 0.8rem; color: var(--text-light); margin-top: 4px; }
.locator-result .features { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.locator-result .feature-tag {
  font-size: 0.7rem; font-weight: 500; padding: 3px 10px;
  border-radius: 50px; background: var(--green-light); color: var(--green);
}

.locator-map-area {
  position: relative; background: var(--gray-100);
  display: flex; align-items: center; justify-content: center;
  min-height: 500px;
}
.locator-map-placeholder {
  text-align: center; color: var(--text-light);
}
.locator-map-placeholder svg { width: 80px; height: 80px; margin-bottom: 16px; opacity: 0.5; }
.locator-map-placeholder p { font-size: 0.9rem; }

/* Suggestion Dropdown */
.search-suggestions {
  display: none; position: absolute; top: 100%; left: 0; right: 0;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius);
  box-shadow: var(--shadow-lg); z-index: 100; margin-top: 4px;
}
.search-suggestions.open { display: block; }
.search-suggestions .suggestion-item {
  padding: 12px 16px; font-size: 0.9rem; cursor: pointer; transition: var(--transition);
}
.search-suggestions .suggestion-item:hover { background: var(--gray-100); }

/* ---- Footer ---- */
.site-footer { background: var(--forest); color: var(--white); padding: 60px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; margin-bottom: 48px; }

.footer-col h4 {
  font-family: 'DM Sans', sans-serif; font-size: 0.85rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 20px;
  color: rgba(255,255,255,0.7); cursor: default;
}
.footer-col a {
  display: block; font-size: 0.85rem; color: rgba(255,255,255,0.6);
  padding: 4px 0; transition: var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px;
  font-size: 0.8rem; color: rgba(255,255,255,0.5);
}

.social-links { display: flex; gap: 16px; }
.social-links a { color: rgba(255,255,255,0.6); transition: var(--transition); font-size: 0.85rem; }
.social-links a:hover { color: var(--white); }

/* ---- Cookie Banner ---- */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: var(--white); border-top: 1px solid var(--gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.08); padding: 20px 0;
  transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { display: none; }
.cookie-inner {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; flex-wrap: wrap;
}
.cookie-inner h4 { font-family: 'DM Sans', sans-serif; font-size: 0.9rem; margin-bottom: 4px; }
.cookie-inner p { font-size: 0.8rem; color: var(--text-light); max-width: 600px; }
.cookie-btns { display: flex; gap: 10px; flex-shrink: 0; }

/* ---- Responsive ---- */
@media (max-width: 1024px) {
  .two-col { grid-template-columns: 1fr; gap: 32px; }
  .card-visual { min-height: 260px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 440px; margin: 0 auto; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid var(--gray-200); padding-bottom: 20px; }
  .menu-sidebar h3 { display: none; }
  .menu-sidebar a { display: inline-block; padding: 6px 14px; border-radius: 50px; font-size: 0.8rem; border: 1px solid var(--gray-200); }
  .menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green); color: var(--white); border-color: var(--green); }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-map-area { min-height: 300px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .partnerships { grid-template-columns: 1fr; }
  .steps-row { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .biz-gifting { flex-direction: column; text-align: center; }
  .nav-main { display: none; }
  .menu-toggle { display: flex; }

  .nav-mobile {
    display: none; position: fixed; top: var(--header-h); left: 0; right: 0; bottom: 0;
    background: var(--white); z-index: 999; flex-direction: column; padding: 24px;
  }
  .nav-mobile.open { display: flex; }
  .nav-mobile a {
    display: block; padding: 14px 20px; font-size: 1.05rem; font-weight: 500;
    border-radius: var(--radius); transition: var(--transition);
  }
  .nav-mobile a:hover { background: var(--gray-100); }
  .nav-mobile .mobile-actions { margin-top: 24px; padding-top: 24px; border-top: 1px solid var(--gray-200); display: flex; flex-direction: column; gap: 12px; }
}

@media (max-width: 768px) {
  .hero { min-height: 420px; }
  .hero-content { padding: 60px 0; }
  .hero-image { width: 300px; height: 300px; right: -120px; }
  .footer-grid { grid-template-columns: 1fr; }

  .footer-col h4 {
    cursor: pointer; position: relative; padding-right: 24px; margin-bottom: 0; padding: 12px 0;
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }
  .footer-col h4::after {
    content: '+'; position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
    font-size: 1.2rem; transition: var(--transition);
  }
  .footer-col.open h4::after { content: '−'; }
  .footer-col-links { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
  .footer-col.open .footer-col-links { max-height: 600px; }
  .footer-col a { padding: 6px 0; }

  .section { padding: 48px 0; }
  .promo-strip { flex-direction: column; text-align: center; }
  .locator-sidebar { border-right: none; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-btns { justify-content: center; }
  .header-inner { padding: 0 16px; }
  .container { padding: 0 16px; }
}

@media (max-width: 480px) {
  .hero { min-height: 360px; }
  .hero h1 { font-size: 1.8rem; }
  .carousel-card { flex: 0 0 220px; }
  .redemption-card { padding: 24px; }
}

